package com.weatherapp.servlet;
import com.weatherapp.db.Database;import com.weatherapp.security.PasswordUtil;import com.weatherapp.util.Json;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;import java.sql.*;import java.util.*;
@WebServlet("/api/login") public class LoginServlet extends BaseServlet{
 protected void doPost(HttpServletRequest req,HttpServletResponse res)throws IOException{try{Map<String,Object> b=Json.M.readValue(Json.body(req),Map.class);String mobile=String.valueOf(b.getOrDefault("mobile",""));String pw=String.valueOf(b.getOrDefault("password",""));if(mobile.isBlank()||pw.isBlank())throw new Exception("Mobile number and password are required.");try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("SELECT UserID,FullName,PasswordHash,PasswordSalt,CityID FROM Users WHERE Mobile=? AND IsActive=True")){p.setString(1,mobile.trim());try(ResultSet r=p.executeQuery()){if(!r.next()||!PasswordUtil.matches(pw,r.getString("PasswordSalt"),r.getString("PasswordHash")))throw new Exception("Invalid mobile number or password.");HttpSession s=req.getSession(true);s.setAttribute("UserID",r.getInt("UserID"));s.setAttribute("UserName",r.getString("FullName"));s.setAttribute("UserCityID",r.getInt("CityID"));Json.write(res,Map.of("ok",true));}}}catch(Exception e){res.setStatus(400);Json.write(res,Map.of("ok",false,"message",e.getMessage()));}}
}
